#!/usr/bin/env node
/**
 * build-canonical-skills-bundle — codegen the canonical skills/<name>/SKILL.md
 * into a bundled TS module so the React Native runtime can offer an in-app
 * "Add canonical skills" action (the repo markdown isn't otherwise bundled).
 *
 * Writes src/lib/canonicalSkills.generated.ts. Kept in sync by
 * smoke:canonical-skills (fails if the committed bundle drifts from the files).
 *
 * Regenerate: npm run build:canonical-skills-bundle
 */

import { readFileSync, readdirSync, existsSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), '..');
const skillsDir = join(repoRoot, 'skills');
const outPath = join(repoRoot, 'src', 'lib', 'canonicalSkills.generated.ts');

function parseFrontmatter(content) {
  const m = content.match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
  const out = { name: '', description: '', version: '1.0.0', tags: [] };
  if (!m) return out;
  for (const line of m[1].split('\n')) {
    const kv = line.match(/^([a-zA-Z_][a-zA-Z0-9_]*):\s*(.+?)\s*$/);
    if (!kv) continue;
    const value = kv[2].replace(/^['"]|['"]$/g, '');
    if (kv[1] === 'name') out.name = value;
    else if (kv[1] === 'description') out.description = value;
    else if (kv[1] === 'version') out.version = value;
    else if (kv[1] === 'tags') out.tags = value.replace(/^\[|\]$/g, '').split(',').map((s) => s.trim().replace(/^['"]|['"]$/g, '')).filter(Boolean);
  }
  return out;
}

const skills = readdirSync(skillsDir, { withFileTypes: true })
  .filter((e) => e.isDirectory() && existsSync(join(skillsDir, e.name, 'SKILL.md')))
  .map((e) => e.name)
  .sort()
  .map((name) => {
    const content = readFileSync(join(skillsDir, name, 'SKILL.md'), 'utf8');
    const fm = parseFrontmatter(content);
    return { name: fm.name || name, description: fm.description, version: fm.version, tags: fm.tags, content };
  });

const banner = `// AUTO-GENERATED by scripts/build-canonical-skills-bundle.mjs — do not edit by hand.
// Source: skills/<name>/SKILL.md. Regenerate: npm run build:canonical-skills-bundle
// Validated in sync by: npm run smoke:canonical-skills
`;

const body = `${banner}
export interface CanonicalSkill {
  name: string;
  description: string;
  version: string;
  tags: string[];
  /** Full SKILL.md (frontmatter + body) — stored in circle_skills.content. */
  content: string;
}

export const CANONICAL_SKILLS: CanonicalSkill[] = ${JSON.stringify(skills, null, 2)};
`;

writeFileSync(outPath, body);
console.log(`Wrote ${outPath} with ${skills.length} skill(s): ${skills.map((s) => s.name).join(', ')}`);
